import{_ as l,C as p,o as a,c,a4 as t,b as i,w as s,a as r,E as o,a5 as d}from"./chunks/framework.DpieW3qv.js";const y=JSON.parse('{"title":"Producer Guide","description":"","frontmatter":{"title":"Producer Guide"},"headers":[],"relativePath":"guides/producer-workflow.md","filePath":"guides/producer-workflow.md","lastUpdated":null}'),h={name:"guides/producer-workflow.md"};function u(m,e,b,g,k,f){const n=p("Mermaid");return a(),c("div",null,[e[2]||(e[2]=t('<h1 id="producer-guide" tabindex="-1">Producer Guide <a class="header-anchor" href="#producer-guide" aria-label="Permalink to &quot;Producer Guide&quot;">​</a></h1><p>One guide for web producers: daily workflow, guards, and (optional) assessment for 4 producers (2 per brand).</p><table tabindex="0"><thead><tr><th>Use this section</th><th>When</th></tr></thead><tbody><tr><td><strong>Daily workflow</strong> (below)</td><td>Your main reference: pull → preview → push → commit. (<code>make push</code> auto-generates email)</td></tr><tr><td><a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a></td><td>First-time setup: install, then <code>make status</code> (runs setup if no config).</td></tr><tr><td><a href="/ocapi-docs.github.io/guides/multi-producer.html">Multi-Producer</a></td><td>Working with a partner on the same brand (2 per brand).</td></tr><tr><td><a href="/ocapi-docs.github.io/guides/ecomm-workflow.html">Ecomm (Smartsheet)</a></td><td>Smartsheet/ecomm workflow and data flow.</td></tr><tr><td><a href="#appendix-assessment-for-4-producers">Assessment for 4 producers</a></td><td>Optional: fit, gaps, and recommendations for teams moving from manual.</td></tr></tbody></table><p>Start with <a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a>, then use the daily workflow below. If you share a brand with another producer, see <a href="/ocapi-docs.github.io/guides/multi-producer.html">Multi-Producer</a>. For Smartsheet/ecomm, see <a href="/ocapi-docs.github.io/guides/ecomm-workflow.html">Ecomm (Smartsheet)</a>.</p><hr><h2 id="principle-use-make-only" tabindex="-1">Principle: Use Make Only <a class="header-anchor" href="#principle-use-make-only" aria-label="Permalink to &quot;Principle: Use Make Only&quot;">​</a></h2><p><strong>You do not need to run <code>node</code> directly.</strong> All producer commands are:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">comman</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>make help</code> shows the full list. If a developer asks you to run a Node script, ask them to expose it via <code>make</code> instead.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Wireframe → preview → push to staging. Building happens automatically (<code>make pull</code> auto-builds new dates; <code>make preview</code> auto-builds if stale). The changeout email is generated automatically. Excel time-only values are interpreted as UTC; the CLI shows dates and times in your local time.</p>',12)),(a(),i(d,null,{default:s(()=>[o(n,{id:"mermaid-81",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20START(%5BStart%20of%20day%5D)%20--%3E%20PULL%5B%22make%20pull%3Cbr%2F%3EGit%20sync%20%2B%20fetch%20data%20%2B%20auto-build%22%5D%0A%20%20%20%20PULL%20--%3E%20STATUS%5B%22make%20status%3Cbr%2F%3EDashboard%20%E2%80%94%20pick%20a%20date%22%5D%0A%20%20%20%20STATUS%20--%3E%20PREVIEW%5B%22make%20preview%3Cbr%2F%3EAuto-builds%20if%20stale%20%2B%20compose%20%2B%20browse%22%5D%0A%0A%20%20%20%20PREVIEW%20--%3E%20PUSH%5B%22make%20push%22%5D%0A%0A%20%20%20%20PUSH%20--%3E%20VALIDATE%7BValidation%7D%0A%20%20%20%20VALIDATE%20--%3E%7CPass%7C%20SYNC%5B%22Sync%20to%20SFCC%20staging%22%5D%0A%20%20%20%20VALIDATE%20--%3E%7CErrors%7C%20FIX%5B%22Fix%20data%20in%20Excel%3Cbr%2F%3Ethen%20make%20pull%22%5D%0A%20%20%20%20FIX%20--%3E%20PULL%0A%0A%20%20%20%20SYNC%20--%3E%20REPLICATE%5B%22make%20replicate%3Cbr%2F%3EReplication%20steps%22%5D%0A%20%20%20%20REPLICATE%20--%3E%20COMMIT%5B%22make%20commit%3Cbr%2F%3ESave%20to%20Git%22%5D%0A%20%20%20%20COMMIT%20--%3E%20ANOTHER%7BAnother%20date%3F%7D%0A%20%20%20%20ANOTHER%20--%3E%7CYes%7C%20STATUS%0A%20%20%20%20ANOTHER%20--%3E%7CNo%7C%20END(%5BEnd%20of%20day%5D)%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t(`<p><strong>Entry point:</strong> <strong><code>make status</code></strong> is the main entry point. On first run with no configuration, it runs setup (view/edit config), then continues to the dashboard. It’s your dashboard. It shows what’s live, synced, ready to push, or needs a build. When the wireframe has start and end times, status shows which refresh is on the homepage right now (<strong>Current live</strong>) and displays time ranges on each row so you can see which refresh covers which period. Picking a refresh from the status picker sets it as your active refresh, then you choose an action (Preview / Browse files, Push, etc.) from the same screen.</p><p>Core flow:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make pull  →  make preview  →  make push  →  make replicate  →  make commit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Building happens automatically: <code>make pull</code> auto-builds new dates after fetching, and <code>make preview</code> auto-builds if data is stale (shows diff + approval prompt). <code>make push</code> auto-generates the changeout email (copied to clipboard) and points to <code>make replicate</code> as the next step.</p><p>You don&#39;t need to change configs or templates in normal use—the developer manages those. <strong>You don&#39;t need to type dates or refresh numbers:</strong> after <code>make pull</code> you pick your working date once; the app remembers it for <code>make preview</code>, <code>make push</code>, and the rest. Flags like <code>DATE=</code> or <code>REFRESH=</code> are for testing and automation, not daily use.</p><hr><h2 id="starting-your-day" tabindex="-1">Starting Your Day <a class="header-anchor" href="#starting-your-day" aria-label="Permalink to &quot;Starting Your Day&quot;">​</a></h2><h3 id="step-1-status-or-pull" tabindex="-1">Step 1: Status or Pull <a class="header-anchor" href="#step-1-status-or-pull" aria-label="Permalink to &quot;Step 1: Status or Pull&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>or</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong><code>make status</code></strong> is the single entry point: if you have no config, it runs setup first, then opens the hub. <strong><code>make pull</code></strong> is an alternative that fetches data and auto-builds, then opens the same status hub. Pull does four things:</p><ol><li><strong>Git pull</strong> — syncs your local files with the rest of the team</li><li><strong>Fetch</strong> — parses the latest Excel/Smartsheet into refresh data (progress: &quot;Fetching data … Parsing {file}&quot;)</li><li><strong>Auto-build</strong> — builds only dates that don&#39;t have a build yet (progress: &quot;Building new dates …&quot; or &quot;All dates already built&quot;)</li><li><strong>Status hub</strong> — opens the status dashboard</li></ol><p>Use <strong>arrow keys</strong> to move, <strong>Enter</strong> to select a refresh. That becomes your <strong>sticky working date</strong> for all following commands. From the same screen you can run an action (Browse files, Push, etc.) or press <strong>q</strong> to exit.</p><details><summary>Producer thinking &amp; blocking errors</summary><p>After pull: <em>&quot;Got the data. Now I&#39;ll pick the date I&#39;m working on.&quot;</em></p><p><strong>Blocking error (no Smartsheet config):</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ❌ Failed to fetch from smartsheet: Smartsheet sheet ID not configured.</span></span>
<span class="line"><span>  Set SMARTSHEET_SHEET_ID_LOFT env var or add sheetId to config.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>Fix:</strong> Run <code>make setup</code> and configure Smartsheet, or switch to local via the setup wizard.</p></details><h3 id="step-2-preview" tabindex="-1">Step 2: Preview <a class="header-anchor" href="#step-2-preview" aria-label="Permalink to &quot;Step 2: Preview&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Auto-builds if data is stale (shows diff + approval prompt), composes previews, then shows a file browser for the preview/ folder. No <code>DATE=</code> needed — it uses your selected date.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  HOMEPAGE  https://stg.loft.com/?__siteDate=2026-02-12T00:00:00...</span></span>
<span class="line"><span>  PPH       https://stg.loft.com/...</span></span>
<span class="line"><span>  POPUP     https://stg.loft.com/...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>If the date was already built and nothing changed, preview skips the build step and goes straight to the file browser.</p><details><summary>Producer thinking &amp; approval prompts</summary><p><strong>Approval prompt (data changed since last build):</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  🔄 New data detected since last sync — rebuilding.</span></span>
<span class="line"><span>  [Shows diff of changes]</span></span>
<span class="line"><span>  Proceed? (y/n)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><em>&quot;The tool is asking me to confirm. I&#39;ll review the diff and press Enter to approve.&quot;</em></p><p><strong>Already synced:</strong> If someone already pushed this date to SFCC, preview will tell you. Pick a different date from <code>make status</code>, or use the &quot;Force rebuild&quot; action in the status hub if you specifically need to rebuild.</p></details><h3 id="step-3-push" tabindex="-1">Step 3: Push <a class="header-anchor" href="#step-3-push" aria-label="Permalink to &quot;Step 3: Push&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Automatically validates your data before syncing. <strong>You cannot push the same refresh twice</strong> — once synced, the command blocks and tells you to use commit (or <code>make push FORCE=1</code> to re-push if needed). The changeout email is auto-generated and copied to clipboard.</p><p><strong>First push (success):</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ✅ Data quality: all checks passed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  📦 Syncing 2026-02-12/r1: loft-2026-02-12-r1</span></span>
<span class="line"><span>     9 assets, 3 slots</span></span>
<span class="line"><span>  ✅ Synced 2026-02-12/r1: 5 created, 4 updated</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  📋 Email copied to clipboard.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Staging: https://staging.example.com/...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Next: make replicate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>If you run <code>make push</code> again for the same refresh:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  • SFCC already has this date; no changes to sync for 2026-02-12/r1.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Use <code>make push FORCE=1</code> only when you need to re-push (e.g. after a force rebuild).</p><details><summary>Producer thinking &amp; warning prompts</summary><p>When there are warnings (but not errors), the tool may ask:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ⚠  1 warning(s) — use --verbose to see details</span></span>
<span class="line"><span>  Proceed with push? (y/n)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><em>&quot;I&#39;ll review the warning. If it&#39;s minor, I&#39;ll proceed. If not, I&#39;ll fix the data first.&quot;</em></p><p>When already synced: <em>&quot;Already pushed. Use make commit to save, or make push FORCE=1 only if a developer says to re-push.&quot;</em></p></details><p>If validation finds errors, the push stops:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ❌ 3 error(s) — fix before sync:</span></span>
<span class="line"><span>     • Item 5 (HOMEPAGE/hp_top_banner): Missing copy on LAUNCH</span></span>
<span class="line"><span>     • Item 7 (HOMEPAGE/hp_hero): Missing copy on LAUNCH</span></span>
<span class="line"><span>     • Item 12 (POPUP/popup_hero): Missing copy on LAUNCH</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Or fix in Excel, then: make pull → make push</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="step-4-replicate" tabindex="-1">Step 4: Replicate <a class="header-anchor" href="#step-4-replicate" aria-label="Permalink to &quot;Step 4: Replicate&quot;">​</a></h3><p>After push, run <code>make replicate</code> to see the replication steps (staging → production in SFCC Business Manager). This is manual — you&#39;ll follow the steps in the browser.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replicate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="step-5-commit" tabindex="-1">Step 5: Commit <a class="header-anchor" href="#step-5-commit" aria-label="Permalink to &quot;Step 5: Commit&quot;">​</a></h3><p><code>make push</code> auto-generates the changeout email and copies it to clipboard. To regenerate the email: <code>make email</code>.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Saves your work to Git so your partner can see it:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ✔ Committed: loft 2026-02-12 done</span></span>
<span class="line"><span>  Run &#39;git push&#39; when ready.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h2 id="switching-dates" tabindex="-1">Switching Dates <a class="header-anchor" href="#switching-dates" aria-label="Permalink to &quot;Switching Dates&quot;">​</a></h2><h3 id="via-status-preferred" tabindex="-1">Via status (preferred) <a class="header-anchor" href="#via-status-preferred" aria-label="Permalink to &quot;Via status (preferred)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Pick a different refresh from the dashboard — use arrow keys to navigate, Enter to select. That selection becomes your active refresh, then choose an action (preview, push, etc.).</p><h3 id="direct-set" tabindex="-1">Direct set <a class="header-anchor" href="#direct-set" aria-label="Permalink to &quot;Direct set&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DATE=2026-02-14</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  ✔ Selected 2026-02-14 (Valentine&#39;s Day)</span></span>
<span class="line"><span>  Status: · NEW — needs make preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="override-for-one-command" tabindex="-1">Override for one command <a class="header-anchor" href="#override-for-one-command" aria-label="Permalink to &quot;Override for one command&quot;">​</a></h3><p>Any command accepts <code>DATE=</code> to override the sticky selection without changing it:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DATE=2026-02-10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Preview 02/10 without switching</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h2 id="switching-data-source" tabindex="-1">Switching Data Source <a class="header-anchor" href="#switching-data-source" aria-label="Permalink to &quot;Switching Data Source&quot;">​</a></h2><p>To switch between local Excel and Smartsheet:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Choose <strong>Edit configuration</strong> and select your data source. Next <code>make pull</code> will fetch from the new source. Switching to Smartsheet requires <code>SMARTSHEET_API_KEY</code> in <code>.env</code> (your developer sets this up). To switch back to local, run <code>make setup</code> again and choose <strong>Local Excel file</strong>.</p><hr><h2 id="switching-ocapi-sfcc-sync" tabindex="-1">Switching OCAPI (SFCC Sync) <a class="header-anchor" href="#switching-ocapi-sfcc-sync" aria-label="Permalink to &quot;Switching OCAPI (SFCC Sync)&quot;">​</a></h2><p>To check whether OCAPI sync is enabled:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Shows <code>OCAPI: enabled</code> or <code>disabled</code>. To toggle: run <code>make setup</code>, choose <strong>Edit configuration</strong>, and toggle the OCAPI option. Pushing to SFCC requires the SFCC env vars in <code>.env</code>.</p><hr><h2 id="force-rebuild-flow" tabindex="-1">Force Rebuild Flow <a class="header-anchor" href="#force-rebuild-flow" aria-label="Permalink to &quot;Force Rebuild Flow&quot;">​</a></h2><p>After a template edit (e.g., fixing a typo in the homepage HTML):</p><ol><li>Run <code>make status</code> and pick the refresh</li><li>Choose <strong>&quot;Force rebuild&quot;</strong> from the action menu</li><li>Then choose <strong>&quot;Push to staging&quot;</strong> (use <code>make push FORCE=1</code> if the refresh was already synced)</li><li><code>make commit</code> to save</li></ol><hr><h2 id="managing-assets-for-sfcc-brands" tabindex="-1">Managing assets for SFCC brands <a class="header-anchor" href="#managing-assets-for-sfcc-brands" aria-label="Permalink to &quot;Managing assets for SFCC brands&quot;">​</a></h2><p><strong>How assets are managed:</strong> When you run <strong><code>make push</code></strong>, the CLI syncs campaign content to SFCC for the <strong>current brand</strong> (loft or ann). Each zone in your wireframe has an <strong>action</strong> (LAUNCH, UPDATE, REMOVE, NO_CHANGE). Push creates new content assets (LAUNCH), updates existing ones (UPDATE), or removes them from SFCC (REMOVE). That is how producers manage assets day to day—by editing the Excel/Smartsheet and pushing.</p><p><strong>Per brand:</strong> Configuration is one brand at a time. Data, refreshes, and the <strong>asset registry</strong> (which tracks current asset IDs per zone) live under <code>dev-env/{brand}/</code>. To work on the other brand, run <code>make setup</code> and switch brand. Each brand’s assets in SFCC are separate.</p><p><strong>Dev / advanced:</strong> If a developer needs to push only asset HTML (no campaign/slot changes) or remove a refresh from SFCC and local:</p><ul><li><strong><code>make upload</code></strong> — Upload content assets only for the selected refresh (hotfix).</li><li><strong><code>make delete DATE=...</code></strong> — Remove a refresh from SFCC and local (cleanup, cancelled campaigns).</li></ul><p>For <strong>tracking and future analysis</strong>, the asset registry records which asset ID is current for each zone (enables NO_CHANGE, asset reuse across refreshes):</p><ul><li><strong><code>make registry</code></strong> — Show, bootstrap, or clear the asset registry for the current brand.</li></ul><p>See <a href="/ocapi-docs.github.io/cli/upload.html">upload</a>, <a href="/ocapi-docs.github.io/cli/delete.html">delete</a>, and <a href="/ocapi-docs.github.io/cli/registry.html">registry</a> for details. For normal producer workflow, <strong><code>make push</code></strong> is enough.</p><hr><h2 id="status-dashboard" tabindex="-1">Status Dashboard <a class="header-anchor" href="#status-dashboard" aria-label="Permalink to &quot;Status Dashboard&quot;">​</a></h2><p>Run <code>make status</code> at any time to see the dashboard and pick a refresh:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</span></span>
<span class="line"><span>  LOFT | STATUS                                          Thu, Feb 13</span></span>
<span class="line"><span>━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</span></span>
<span class="line"><span>  LIVE = on site now · SYNCED = pushed · … · BUILD = needs build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  4 refreshes · 1 live · 1 ready · 1 to build · 1 new</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Current: 2026-02-12 / r1 - 3pm</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Select a refresh and press Enter for actions (q to exit)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    2026-02-08  r1 - 3am   NFP 70 / FP 50%           ● LIVE</span></span>
<span class="line"><span>    2026-02-10  r1 - 3pm   NFP 60 / FP 40%           ✔ READY</span></span>
<span class="line"><span>  ❯ 2026-02-12  r1 - 3pm   EP 50%                    ○ BUILD   ← selected</span></span>
<span class="line"><span>    2026-02-14  r1 - 3am   Valentine&#39;s Day           · NEW</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>Selecting a row sets that refresh as active; you then choose an action — Preview / Browse files, Push, Commit, Force rebuild, Generate email, View data quality, or Pull — based on the current state of the refresh.</p><blockquote><p>If output is piped or there is no TTY, status falls back to a table view with a Next Step column.</p></blockquote><h2 id="date-states" tabindex="-1">Date States <a class="header-anchor" href="#date-states" aria-label="Permalink to &quot;Date States&quot;">​</a></h2>`,81)),(a(),i(d,null,{default:s(()=>[o(n,{id:"mermaid-353",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20NEW%3A%20make%20pull%20finds%20new%20date%0A%20%20%20%20NEW%20--%3E%20READY%3A%20auto-build%20(pull%20%2F%20preview)%0A%20%20%20%20READY%20--%3E%20SYNCED%3A%20make%20push%20(auto-generates%20email)%0A%20%20%20%20SYNCED%20--%3E%20SYNCED%3A%20make%20commit%0A%0A%20%20%20%20READY%20--%3E%20READY%3A%20Force%20rebuild%20(status%20action)%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<table tabindex="0"><thead><tr><th>State</th><th>Meaning</th><th>Files Present</th></tr></thead><tbody><tr><td><strong>NEW</strong></td><td>Data fetched, not yet built</td><td><code>refresh.json</code></td></tr><tr><td><strong>READY</strong></td><td>Built, ready to push</td><td>+ <code>ocapi-payload.json</code></td></tr><tr><td><strong>SYNCED</strong></td><td>Pushed to SFCC staging</td><td>+ <code>refresh.json</code> sync section</td></tr></tbody></table><hr><p><strong>Quick reference:</strong> <code>pull</code> → <code>status</code> (pick refresh) → <code>preview</code> → <code>push</code> (auto-generates email) → <code>replicate</code> → <code>commit</code>. All use your sticky date unless you pass <code>DATE=</code>. Use <code>make email</code> to regenerate the email standalone. For detailed output, add <code>VERBOSE=1</code> before any command.</p><h2 id="quick-reference-options" tabindex="-1">Quick Reference: Options <a class="header-anchor" href="#quick-reference-options" aria-label="Permalink to &quot;Quick Reference: Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want…</th><th>Use</th></tr></thead><tbody><tr><td>Skip confirmation prompts (CI/scripts)</td><td><code>make push YES=1</code></td></tr><tr><td>Force rebuild after template edit</td><td><code>make status</code> → &quot;Force rebuild&quot; action</td></tr><tr><td>Force re-push (developer said so)</td><td><code>make push FORCE=1</code></td></tr><tr><td>Target a specific date</td><td><code>make preview DATE=2026-02-14</code></td></tr><tr><td>Target a specific refresh (r1, r2)</td><td><code>make push REFRESH=r2</code></td></tr><tr><td>All refreshes in a date</td><td><code>make push ALL=1</code></td></tr><tr><td>Fetch Smartsheet and convert</td><td><code>make pull CONVERT=1</code></td></tr><tr><td>Use local Excel</td><td><code>make setup</code> (choose Local Excel)</td></tr><tr><td>Use Smartsheet</td><td><code>make setup</code> (choose Smartsheet)</td></tr><tr><td>Enable SFCC sync</td><td><code>make setup</code> (enable OCAPI)</td></tr><tr><td>Disable SFCC sync</td><td><code>make setup</code> (disable OCAPI)</td></tr><tr><td>Switch brand</td><td><code>make setup</code> (choose brand)</td></tr><tr><td>Upload assets only / delete refresh / registry (dev)</td><td><code>make dev</code> then upload, delete, or registry</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a> — First-time setup</li><li><a href="/ocapi-docs.github.io/guides/multi-producer.html">Multi-Producer Guide</a> — Working with your partner</li><li><a href="/ocapi-docs.github.io/reference/commands.html">Commands Reference</a> — Full command list</li><li><a href="/ocapi-docs.github.io/troubleshooting/common-errors.html">Common Errors</a> — Error messages and fixes</li></ul><hr><h2 id="appendix-assessment-for-4-producers" tabindex="-1">Appendix: Assessment for 4 producers <a class="header-anchor" href="#appendix-assessment-for-4-producers" aria-label="Permalink to &quot;Appendix: Assessment for 4 producers&quot;">​</a></h2><p>Optional reading for leads: fit and gaps for <strong>4 web producers</strong> (2 LOFT, 2 Ann Taylor) moving from a manual process. Daily how-to is in the sections above.</p><p><strong>Fit:</strong> Single flow (pull → preview → push → commit), sticky date, auto-builds, build/sync guards, data quality before push, email auto-generated by push, multi-producer safety via Git. No need to touch configs/templates in normal use.</p><p><strong>Gaps to know:</strong> (1) One brand per config—use <code>make setup</code> and choose brand if working both. (2) Data errors fixed in Excel/Smartsheet, then <code>make pull</code> and retry. (3) Multiple refreshes (r1, r2): use picker or <code>REFRESH=r2</code> / <code>ALL=1</code>. (4) <code>make replicate</code> is checklist only; STG → POD manual. (5) First-time: <code>make setup</code>, SFCC env vars, <code>make health</code>—see <a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a>. <strong>2 per brand:</strong> own machine and sticky date; always <code>make pull</code> first, <code>make commit</code> + <code>git push</code> after push/done. Force rebuild: <code>make status</code> → &quot;Force rebuild&quot; action → <code>make push</code> (use <code>FORCE=1</code> if already synced).</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Assessment</th></tr></thead><tbody><tr><td><strong>Fit (2 per brand)</strong></td><td>Good: sticky date, guards, Git sharing, clear flow.</td></tr><tr><td><strong>Transition from manual</strong></td><td>Good: one linear flow, data quality, preview; source of truth = Excel.</td></tr><tr><td><strong>Brand / multi-refresh / replicate</strong></td><td>Documented; replicate is manual by design.</td></tr></tbody></table>',14))])}const w=l(h,[["render",u]]);export{y as __pageData,w as default};
